using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Windows;
using System.Web.Script.Serialization;
class DesktopMovementTests {
 static int checks,failures;static void Check(bool ok,string name){checks++;if(!ok)failures++;Console.WriteLine((ok?"PASS ":"FAIL ")+name);}
 static PetScreenArea Screen(double x,double y,double w,double h,double taskbar=0){return new PetScreenArea{Bounds=new Rect(x,y,w,h),Work=new Rect(x,y,w,h-taskbar)};}
 static bool Covered(PetScreenArea[] screens,double x,double y,double w,double h){var r=new Rect(x+.001,y+.001,w-.002,h-.002);double covered=0;foreach(var s in screens){var part=Rect.Intersect(r,s.Bounds);if(!part.IsEmpty)covered+=part.Width*part.Height;}return covered+1>=r.Width*r.Height;}
 static bool Travel(PetScreenArea[] screens,Point start,Point target,out Point end,double w=280,double h=330){var map=new DesktopMovement(screens,w,h);double x=start.X,y=start.Y;bool safe=true,done=false;for(int i=0;i<3000&&!done;i++){var old=new Point(x,y);done=map.Step(ref x,ref y,target,8);safe&=Covered(screens,x,y,w,h)&&(new Point(x,y)-old).Length<=8.0001;}end=new Point(x,y);return safe&&done;}
 [STAThread]static int Main(string[] args){Directory.CreateDirectory(args[0]);try{double x=20,y=300;MovementLogic.Step(ref x,ref y,-400,300,1000,0,0,1640,702);Check(x==0,"legacy per-monitor clamp reproduces blocked crossing");var pair=new[]{Screen(0,0,1920,1080,48),Screen(-1920,0,1920,1080,48)};Point end;bool safe=Travel(pair,new Point(20,351),new Point(-600,351),out end);Check(safe&&end.X==-600,"continuous crossing into negative-coordinate screen");safe=Travel(pair,new Point(-600,351),new Point(400,500),out end);Check(safe&&end.X==400&&end.Y==500,"return crossing keeps full window visible and step budget");var stacked=new[]{Screen(0,0,1920,1080,48),Screen(0,1080,1920,1080,48)};safe=Travel(stacked,new Point(500,600),new Point(500,1400),out end);Check(safe&&end.Y==1400,"vertical crossing bridges taskbar strip without losing character");var offset=new[]{Screen(0,0,1920,1080,48),Screen(1920,500,1280,1024,48)};safe=Travel(offset,new Point(500,100),new Point(2200,1100),out end);Check(safe&&end.X==2200,"staggered monitors route through shared seam");var l=new[]{Screen(0,0,1920,1080,48),Screen(1920,0,1920,1080,48),Screen(1920,1080,1920,1080,48)};safe=Travel(l,new Point(200,700),new Point(2400,1600),out end);Check(safe&&end.Y==1600,"L layout avoids invisible bounding-box hole");var separated=new[]{Screen(0,0,1920,1080,48),Screen(1960,0,1920,1080,48)};safe=Travel(separated,new Point(200,300),new Point(2400,300),out end);Check(safe&&end.X<=1640,"disconnected screens cannot teleport across empty gap");var narrow=new[]{Screen(0,0,1920,1080,48),Screen(1920,900,1920,1080,48)};safe=Travel(narrow,new Point(200,300),new Point(2400,1000),out end);Check(safe&&end.X<=1640,"portal narrower than character is not traversed");var map=new DesktopMovement(pair,280,330);Check(map.Destinations(new Point(10,300)).Length==2,"roam and patrol can select both connected screens");Check(new DesktopMovement(separated,280,330).Destinations(new Point(10,300)).Length==1,"random choices exclude disconnected destinations");var clamp=new DesktopMovement(new[]{pair[0]},280,330).ClampToScreen(new Point(-1200,300));Check(clamp.X==0&&clamp.Y==300,"unplugged screen position safely returns to visible work area");map=new DesktopMovement(new[]{Screen(0,0,800,600,48)},280,330);x=100;y=100;bool arrived=map.Step(ref x,ref y,new Point(200,100),10);Check(!arrived&&x==110&&y==100,"single monitor preserves straight-line speed");map=new DesktopMovement(pair,280,330);x=20;y=351;map.Step(ref x,ref y,new Point(-600,351),100);var before=new Point(x,y);map.Step(ref x,ref y,new Point(800,200),8);Check((new Point(x,y)-before).Length<=8.0001,"cursor target change does not jump across screen");map=new DesktopMovement(new[]{Screen(0,0,280,330)},280,330);x=0;y=0;Check(map.Step(ref x,ref y,new Point(20,20),8)&&x==0&&y==0,"exact-fit screen remains valid");Check(new DesktopMovement(new PetScreenArea[0],280,330).Destinations(new Point()).Length==0,"empty display snapshot has safe no-target behavior");var above=new[]{Screen(0,0,1920,1080,48),Screen(0,-1080,1920,1080,48)};safe=Travel(above,new Point(500,300),new Point(600,-600),out end);Check(safe&&end.Y==-600,"negative vertical monitor coordinates supported");
 }catch(Exception e){failures++;Console.WriteLine(e);}File.WriteAllText(Path.Combine(args[0],"movement-results.json"),new JavaScriptSerializer().Serialize(new{checks,failures}));return failures==0?0:1;}
}
